bool read_embedded_asset(const std::string &path,std::string &out){std::string normalized=path;while(normalized.rfind("./",0)==0)normalized.erase(0,2);for(const auto &entry:kEntries)if(normalized==entry.path){out.assign(entry.data,std::strlen(entry.data));return true;}return false;}
